insert into public.experiences (kind, role, company, location, date_label, summary, bullets, tags, sort_order)
select * from (values
  ('work', 'Software Development Lead', 'Private Company', 'Remote', '2026', 'Building and evolving web applications into production-ready web and mobile experiences, working across the full development lifecycle from planning and interface implementation to backend systems, integrations, testing, deployment, and ongoing improvements. I work across frontend and backend development, translate product ideas into working features, troubleshoot production issues, and help shape technical and user-experience decisions as products move from concept to release.', array['Develop and maintain full-stack web applications and mobile-ready experiences.', 'Adapt existing web products for mobile application environments and cross-platform use.', 'Build user-facing features alongside the APIs, services, and data systems that support them.', 'Integrate third-party platforms and services into existing product workflows.', 'Debug application issues across development, testing, and production environments.', 'Contribute to UI/UX improvements, technical architecture, and product iteration.', 'Take ownership of features from initial requirements through implementation, testing, and release.']::text[], '{}'::text[], 10),
  ('work', 'Junior Digital Designer', 'SeekLab Marketing Solutions', 'Hybrid', '2026', 'Creating digital design materials and translating project requirements into clean, user-focused visual experiences. The role allows me to combine design thinking with my technical background, strengthening the way I approach visual communication, interface design, and the overall experience of digital products.', '{}'::text[], '{}'::text[], 20),
  ('work', 'Software Engineer Intern', 'Limitless Lab', 'Internship', '2023', 'Gained hands-on experience in a professional software-development environment while completing my Computer Science degree. I applied concepts learned in university to real development workflows, collaborated on technical tasks, and gained a better understanding of how digital products move from requirements and implementation to testing and delivery.', '{}'::text[], '{}'::text[], 30),
  ('leadership', 'SK Chairperson', 'Sangguniang Kabataan, Barangay Bulihan', 'Barangay Bulihan', '2024', 'Leading youth-centered programs, community initiatives, and council operations while collaborating with local government offices, organizations, and community stakeholders. The role has strengthened my experience in leadership, project management, decision-making, public service, and developing initiatives designed around the actual needs of young people in the community.', '{}'::text[], '{}'::text[], 40),
  ('leadership', 'President', 'Rotaract Club of Malolos Capital', 'Malolos, Bulacan', '2024 – 2026', 'Leading service projects, professional-development activities, and youth-empowerment programs under the organization’s “Service Above Self” mission, while promoting civic responsibility and sustainable community impact.', '{}'::text[], '{}'::text[], 50),
  ('education', 'BS Computer Science', 'University of the Philippines Los Baños', 'Los Baños, Laguna', 'Batch 2022', 'Completed degree.', '{}'::text[], '{}'::text[], 60),
  ('education', 'Law', 'Continuing education', 'School · TODO', 'Ongoing', 'Currently studying law — in progress, not yet completed.', '{}'::text[], '{}'::text[], 70)
) as seed (kind, role, company, location, date_label, summary, bullets, tags, sort_order)
